import Footer from "./components/Footer";
import Header from "./components/Header";
import Body from "./components/Body";
import Image from './images/bg_image_hcmute.png';
// import {Route, BrowserRouter as Router, Routes} from "react-router-dom"
import { useState } from "react";

function App() {
    const backgroundStyle = {
      backgroundImage: `url(${Image})`,
      backgroundSize: 'cover',
      backgroundPosition: 'center',
      backgroundRepeat: 'no-repeat',
      width: '100vw',
      height: '100vh',
      overflow: 'hidden',
      position: 'fixed',
      top: 0,
      left: 0,
      zIndex: -1, // Send the background to the back
    };

  const contentStyle = {
      position: 'relative',
      zIndex: 1, // Place content above the background
      padding: '20px',
      height: '950px', // Ensure content takes full viewport height
      overflowY: "hidden",  // Allow content to scroll
  };

  const [email, setEmail] = useState('');

  return (
    <div className="App">
        <div style={backgroundStyle}></div>
        <div style={contentStyle}>
          <Header email={email}/>
          <hr/>
          <Body setEmail={setEmail}></Body>
          <Footer />
        </div>
    </div>
  );
}

export default App;
